import math
import unittest

from solution import trailing_average


class TrailingAverageTests(unittest.TestCase):
    def test_complete_trailing_windows_include_current_value(self):
        self.assertEqual(
            trailing_average([1, 2, 3, 4, 5], 3),
            [None, None, 2.0, 3.0, 4.0],
        )

    def test_mixed_numeric_values_and_tuple_input(self):
        result = trailing_average((1.5, 2, -0.5, 5), 2)
        expected = [None, 1.75, 0.75, 2.25]
        self.assertEqual(result, expected)
        self.assertIsInstance(result, list)

    def test_window_one_returns_float_averages(self):
        result = trailing_average([3, -2.5, 0], 1)
        self.assertEqual(result, [3.0, -2.5, 0.0])
        for value in result:
            self.assertIs(type(value), float)

    def test_empty_and_window_larger_than_input(self):
        self.assertEqual(trailing_average([], 4), [])
        self.assertEqual(trailing_average([1, 2], 3), [None, None])

    def test_input_is_not_mutated(self):
        values = [1, 2.5, 3]
        before = list(values)
        trailing_average(values, 2)
        self.assertEqual(values, before)

    def test_values_broad_type_error(self):
        for values in (None, "123", {1, 2}, iter([1, 2])):
            with self.subTest(values=values), self.assertRaises(TypeError):
                trailing_average(values, 2)

    def test_invalid_window(self):
        for window in (0, -1, True, False, 2.0, "2"):
            with self.subTest(window=window), self.assertRaises(ValueError):
                trailing_average([], window)

    def test_invalid_elements(self):
        values_cases = [
            [1, True],
            [1, "2"],
            [1, None],
            [1, math.nan],
            [1, math.inf],
            [1, -math.inf],
            [1, 2 + 0j],
        ]
        for values in values_cases:
            with self.subTest(values=values), self.assertRaises(ValueError):
                trailing_average(values, 2)


if __name__ == "__main__":
    unittest.main()

